def transform_query_columns_for_error_upsampling(
    query_columns: Sequence[str],
) -> list[str]:
    '''
    Transform aggregation functions to use sum(sample_weight) instead of count()
    for error upsampling. Only called when all projects are allowlisted.
    '''
    transformed_columns = []
    for column in query_columns:
        stripped = column.strip()
        column_lower = stripped.lower()
        is_count = False
        alias = None

        if column_lower.startswith('count'):
            i = 5
            n = len(column_lower)
            while i < n and column_lower[i].isspace():
                i += 1
            if i < n and column_lower[i] == '(':
                i += 1
                while i < n and column_lower[i].isspace():
                    i += 1
                if i < n and column_lower[i] == ')':
                    i += 1
                    while i < n and column_lower[i].isspace():
                        i += 1
                    if i == n:
                        is_count = True
                    elif column_lower.startswith('as', i):
                        i += 2
                        while i < n and column_lower[i].isspace():
                            i += 1
                        alias_start = i
                        while i < n and (column_lower[i].isalnum() or column_lower[i] == '_'):
                            i += 1
                        if alias_start < i:
                            alias = stripped[alias_start:i]
                            while i < n and column_lower[i].isspace():
                                i += 1
                            if i == n:
                                is_count = True

        if is_count:
            default_alias = 'count'
            transformed_columns.append(f'upsampled_count() as {alias or default_alias}')
        else:
            transformed_columns.append(column)

    return transformed_columns

